const CODE_TO_MAP_NAME: Record<string, string> = {
  GB: 'England',
  US: 'USA',
}

export function codeToMapName(code: string, countryName: string): string {
  return CODE_TO_MAP_NAME[code.toUpperCase()] ?? countryName
}
